async function replyMention(message: Message) {
  const backupResponse = BACKUP_RESPONSES[Math.floor(Math.random() * BACKUP_RESPONSES.length)]!;

  const mayUseAi = await getRedisClient()
    .set(`orbit:ai_reply:${message.author.id}`, '1', 'EX', AI_COOLDOWN_SECONDS, 'NX')
    .catch(() => null);

  if (!mayUseAi) {
    await message.reply(backupResponse);
    return;
  }

  const response = await runAI(
    'Generate a funny Discord bot mention response. Like "Look, I don\'t make the rules. You ping, I show up." or "Not all heroes wear capes. Some just respond to pings.". Just return one funny sentence, it will be displayed in a Discord channel directly',
    ''
  );

  await message.reply(response.status === 'success' ? response.data.response : backupResponse);
}

// Replying to mentions is switched off, as it was in v1. Set this to true to
// turn it back on.
const REPLY_TO_MENTIONS = false;

export default defineEvent({
  name: Events.MessageCreate,
  async execute(message) {
    if (!REPLY_TO_MENTIONS) return;
    if (message.author.bot) return;
    if (!message.mentions.users.has(message.client.user.id)) return;
    if (message.content.includes(`herinner`) || message.content.includes(`remind`)) return;

    try {
      await replyMention(message);
    } catch (error) {
      Logging.error(`Orbit: could not reply to mention: ${error}`);
    }
  },
});
